UNION ALL SELECT 'Preservação: matriz_treinamentos' AS "CHECK",md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM public.matriz_treinamentos r
UNION ALL SELECT 'Preservação: documento_tipos' AS "CHECK",md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM public.documento_tipos r
